function Home() {
  return (
    <div style={{ padding: "15px" }}>
      <h3 style={{ color: "#4CAF50" }}>오늘의 독서</h3>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(2, 1fr)",
        gap: "10px"
      }}>

        <div style={card}>소년이 온다</div>
        <div style={card}>데미안</div>
        <div style={card}>1984</div>
        <div style={card}>노르웨이의 숲</div>

      </div>
    </div>
  );
}

const card = {
  background: "white",
  padding: "20px",
  borderRadius: "15px",
  boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
  textAlign: "center",
  fontWeight: "bold"
};

export default Home;
